/* @lc app=leetcode id=3518 lang=kotlin */ class Solution { fun cb(n: Int, r: Int): Long = if (r < 0 || r > n) 0L else minOf(r, n - r).let { rr -> generateSequence(Pair(1L, 1)) { (a, i) -> if (i > rr || a >= 2_000_000L) null else minOf(2_000_000L, a * (n - rr + i) / i) to i + 1 }.last().first } fun mt(h: IntArray): Long = h.fold(h.sum() to 1L) { (rem, acc), c -> rem - c to minOf(2_000_000L, acc * cb(rem, c)) }.second fun smallestPalindrome(s: String, k: Int): String = IntArray(26).also { h -> s.forEach { h[it - 'a']++ } }.let { cnt -> cnt.map { it / 2 }.toIntArray().let { h -> if (mt(h) < k) "" else LongArray(1) { k.toLong() }.let { kk -> (0 until h.sum()).map { _ -> (0..25).first { c -> h[c] > 0 && h.set(c, h[c] - 1).let { mt(h).let { w -> if (kk[0] <= w) true else kk.set(0, kk[0] - w).let { h.set(c, h[c] + 1) }.let { false } } } } }.let { half -> half.map { 'a' + it }.joinToString("").let { hs -> hs + (0..25).filter { cnt[it] % 2 == 1 }.joinToString("") { ('a' + it).toString() } + hs.reversed() } } } } } }